package checkpoint

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	gogit "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// TestBuildTreeWithChanges_EquivalenceWithFlattenRebuild verifies that
// the ApplyTreeChanges-based buildTreeWithChanges produces identical
// tree hashes to the old FlattenTree+BuildTreeFromEntries approach.
func TestBuildTreeWithChanges_EquivalenceWithFlattenRebuild(t *testing.T) { //nolint:paralleltest // t.Chdir requires non-parallel
	repo, dir := setupTestRepo(t)
	store := NewGitStore(repo)

	// Get the base tree hash from HEAD
	head, err := repo.Head()
	if err != nil {
		t.Fatalf("head: %v", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		t.Fatalf("commit: %v", err)
	}
	baseTreeHash := commit.TreeHash

	// Create modified and deleted files
	modifiedFiles := []string{"file1.txt", "file2.txt"}
	deletedFiles := []string{"file3.txt"}

	// Write modified files to disk
	for _, f := range modifiedFiles {
		path := filepath.Join(dir, f)
		if err := os.WriteFile(path, []byte("modified content for "+f), 0o600); err != nil {
			t.Fatalf("write %s: %v", f, err)
		}
	}

	// Create metadata directory with a file
	metadataDir := ".entire/metadata/test-session"
	metadataDirAbs := filepath.Join(dir, metadataDir)
	if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
		t.Fatalf("mkdir metadata: %v", err)
	}
	if err := os.WriteFile(filepath.Join(metadataDirAbs, "full.jsonl"), []byte(`{"type":"test"}`), 0o600); err != nil {
		t.Fatalf("write transcript: %v", err)
	}

	// Switch to repo dir so paths.WorktreeRoot() resolves correctly
	t.Chdir(dir)

	// --- New approach: ApplyTreeChanges (what buildTreeWithChanges now does) ---
	newHash, err := store.buildTreeWithChanges(context.Background(), baseTreeHash, modifiedFiles, deletedFiles, metadataDir, metadataDirAbs)
	if err != nil {
		t.Fatalf("buildTreeWithChanges (new): %v", err)
	}

	// --- Old approach: FlattenTree + modify map + BuildTreeFromEntries ---
	oldHash := flattenRebuildTree(t, repo, baseTreeHash, modifiedFiles, deletedFiles, metadataDir, metadataDirAbs, dir)

	if newHash != oldHash {
		t.Errorf("tree hash mismatch: new=%s old=%s", newHash, oldHash)
	}
}

// TestAddTaskMetadataToTree_EquivalenceWithFlattenRebuild verifies that
// the ApplyTreeChanges-based addTaskMetadataToTree produces identical trees.
func TestAddTaskMetadataToTree_EquivalenceWithFlattenRebuild(t *testing.T) {
	t.Parallel()

	repo, _ := setupTestRepo(t)
	store := NewGitStore(repo)

	head, err := repo.Head()
	if err != nil {
		t.Fatalf("head: %v", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		t.Fatalf("commit: %v", err)
	}
	baseTreeHash := commit.TreeHash

	// Test without transcripts — the tree structure equivalence is what matters.
	// Transcript processing (chunking, redaction) is covered by integration tests.
	opts := WriteTemporaryTaskOptions{
		SessionID:      "sess-001",
		ToolUseID:      "tool-001",
		AgentID:        "agent-001",
		CheckpointUUID: "uuid-001",
	}

	// New approach (ApplyTreeChanges)
	newHash, err := store.addTaskMetadataToTree(context.Background(), baseTreeHash, opts)
	if err != nil {
		t.Fatalf("addTaskMetadataToTree (new): %v", err)
	}

	// Old approach: manually flatten and rebuild
	oldHash := flattenRebuildTaskMetadata(t, repo, baseTreeHash, opts)

	if newHash != oldHash {
		t.Errorf("tree hash mismatch: new=%s old=%s", newHash, oldHash)
	}
}

// TestAddTaskMetadataToTree_IncrementalPath verifies the incremental checkpoint
// branch of addTaskMetadataToTree produces a valid tree with the expected entry.
// We can't do exact hash comparison because the incremental checkpoint embeds
// time.Now(), so instead we verify the file exists at the correct path in the tree.
func TestAddTaskMetadataToTree_IncrementalPath(t *testing.T) {
	t.Parallel()

	repo, _ := setupTestRepo(t)
	store := NewGitStore(repo)

	head, err := repo.Head()
	if err != nil {
		t.Fatalf("head: %v", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		t.Fatalf("commit: %v", err)
	}

	opts := WriteTemporaryTaskOptions{
		SessionID:           "sess-002",
		ToolUseID:           "tool-002",
		IsIncremental:       true,
		IncrementalType:     "todo_update",
		IncrementalSequence: 3,
		IncrementalData:     []byte(`{"items":["task1","task2"]}`),
	}

	newTreeHash, err := store.addTaskMetadataToTree(context.Background(), commit.TreeHash, opts)
	if err != nil {
		t.Fatalf("addTaskMetadataToTree (incremental): %v", err)
	}

	// Verify the checkpoint file exists at the expected path
	newTree, err := repo.TreeObject(newTreeHash)
	if err != nil {
		t.Fatalf("read new tree: %v", err)
	}

	expectedPath := ".entire/metadata/sess-002/tasks/tool-002/checkpoints/003-tool-002.json"
	file, err := newTree.File(expectedPath)
	if err != nil {
		t.Fatalf("file not found at %s: %v", expectedPath, err)
	}

	content, err := file.Contents()
	if err != nil {
		t.Fatalf("read file contents: %v", err)
	}

	// Verify it's valid JSON with expected fields
	if !strings.Contains(content, `"type": "todo_update"`) {
		t.Errorf("expected type field in content, got: %s", content)
	}
	if !strings.Contains(content, `"tool_use_id": "tool-002"`) {
		t.Errorf("expected tool_use_id field in content, got: %s", content)
	}

	// Verify original files are still present (tree surgery didn't destroy them)
	if _, err := newTree.File("file1.txt"); err != nil {
		t.Errorf("original file1.txt missing from tree after incremental update")
	}
}

// setupTestRepo creates a temporary git repo with some initial files.
func setupTestRepo(t *testing.T) (*gogit.Repository, string) {
	t.Helper()

	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	repo, err := gogit.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("git init: %v", err)
	}

	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("worktree: %v", err)
	}

	// Create initial files
	for _, name := range []string{"file1.txt", "file2.txt", "file3.txt", "src/main.go"} {
		abs := filepath.Join(dir, name)
		if err := os.MkdirAll(filepath.Dir(abs), 0o750); err != nil {
			t.Fatalf("mkdir: %v", err)
		}
		if err := os.WriteFile(abs, []byte("initial content of "+name), 0o600); err != nil {
			t.Fatalf("write: %v", err)
		}
		if _, err := wt.Add(name); err != nil {
			t.Fatalf("add: %v", err)
		}
	}

	// Create .gitignore
	if err := os.WriteFile(filepath.Join(dir, ".gitignore"), []byte(".entire/\n"), 0o600); err != nil {
		t.Fatalf("write .gitignore: %v", err)
	}
	if _, err := wt.Add(".gitignore"); err != nil {
		t.Fatalf("add .gitignore: %v", err)
	}

	_, err = wt.Commit("Initial commit", &gogit.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
	})
	if err != nil {
		t.Fatalf("commit: %v", err)
	}

	return repo, dir
}

// flattenRebuildTree is the old FlattenTree+BuildTreeFromEntries approach
// for comparison in equivalence tests.
func flattenRebuildTree(
	t *testing.T, repo *gogit.Repository,
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs, repoRoot string,
) plumbing.Hash {
	t.Helper()

	baseTree, err := repo.TreeObject(baseTreeHash)
	if err != nil {
		t.Fatalf("tree: %v", err)
	}
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(repo, baseTree, "", entries); err != nil {
		t.Fatalf("flatten: %v", err)
	}

	for _, file := range deletedFiles {
		delete(entries, file)
	}

	for _, file := range modifiedFiles {
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}
		blobHash, mode, blobErr := createBlobFromFile(repo, absPath)
		if blobErr != nil {
			continue
		}
		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(repo, metadataDirAbs, metadataDir, entries); err != nil {
			t.Fatalf("add metadata: %v", err)
		}
	}

	hash, err := BuildTreeFromEntries(repo, entries)
	if err != nil {
		t.Fatalf("build tree: %v", err)
	}
	return hash
}

// flattenRebuildTaskMetadata is the old FlattenTree+BuildTreeFromEntries approach
// for addTaskMetadataToTree comparison.
func flattenRebuildTaskMetadata(
	t *testing.T, repo *gogit.Repository,
	baseTreeHash plumbing.Hash,
	opts WriteTemporaryTaskOptions,
) plumbing.Hash {
	t.Helper()

	baseTree, err := repo.TreeObject(baseTreeHash)
	if err != nil {
		t.Fatalf("tree: %v", err)
	}
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(repo, baseTree, "", entries); err != nil {
		t.Fatalf("flatten: %v", err)
	}

	sessionMetadataDir := ".entire/metadata/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	// Checkpoint.json
	checkpointJSON := []byte(`{
  "session_id": "` + opts.SessionID + `",
  "tool_use_id": "` + opts.ToolUseID + `",
  "checkpoint_uuid": "` + opts.CheckpointUUID + `",
  "agent_id": "` + opts.AgentID + `"
}`)
	blobHash, err := CreateBlobFromContent(repo, checkpointJSON)
	if err != nil {
		t.Fatalf("create blob: %v", err)
	}
	cpPath := taskMetadataDir + "/checkpoint.json"
	entries[cpPath] = object.TreeEntry{
		Name: cpPath,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

package checkpoint

import (
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// TreeChange represents a single file change within a tree.
// Use a nil Entry to indicate deletion.
type TreeChange struct {
	// Path is the full path within the tree (e.g., "src/pkg/handler.go").
	Path string
	// Entry is the new tree entry. Nil means delete the file at Path.
	Entry *object.TreeEntry
}

// MergeMode controls how entries at the leaf directory are handled by UpdateSubtree.
type MergeMode int

const (
	// ReplaceAll replaces the entire leaf directory contents with the new entries.
	ReplaceAll MergeMode = iota
	// MergeKeepExisting merges new entries into the existing leaf directory,
	// keeping existing entries that are not overwritten (unless in DeleteNames).
	MergeKeepExisting
)

// UpdateSubtreeOptions configures the behavior of UpdateSubtree.
type UpdateSubtreeOptions struct {
	// MergeMode controls how entries at the leaf directory are handled.
	MergeMode MergeMode
	// DeleteNames lists entry names (at the leaf directory level) to delete.
	// Only applicable when MergeMode is MergeKeepExisting.
	DeleteNames []string
}

// UpdateSubtree replaces or creates a subtree at the given path within an existing tree.
// It walks the tree path, replacing only the entries along the modified path.
// All sibling entries at each level retain their original hashes — no re-reading needed.
//
// pathSegments is the directory path split into segments (e.g., ["a3", "b2c4d5e6f7"]).
// newEntries are the files/dirs to place at the leaf directory.
// Returns the new root tree hash.
func UpdateSubtree(
	repo *git.Repository,
	rootTreeHash plumbing.Hash,
	pathSegments []string,
	newEntries []object.TreeEntry,
	opts UpdateSubtreeOptions,
) (plumbing.Hash, error) {
	if len(pathSegments) == 0 {
		return buildLeafTree(repo, rootTreeHash, newEntries, opts)
	}

	// Read the current tree at this level
	// Get all entries in the tree and add them to the currentEntries slice
	var currentEntries []object.TreeEntry
	if rootTreeHash != plumbing.ZeroHash {
		tree, err := repo.TreeObject(rootTreeHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to read tree %s: %w", rootTreeHash, err)
		}
		currentEntries = tree.Entries
	}

	targetDir := pathSegments[0]
	remainingPath := pathSegments[1:]

	// Find the existing subtree entry for targetDir
	var existingSubtreeHash plumbing.Hash
	found := false
	for _, entry := range currentEntries {
		if entry.Name == targetDir && entry.Mode == filemode.Dir {
			existingSubtreeHash = entry.Hash
			found = true
			break
		}
	}

	// Recurse into the subtree
	newSubtreeHash, err := UpdateSubtree(repo, existingSubtreeHash, remainingPath, newEntries, opts)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	// Build a new tree at this level with the updated subtree entry
	updatedEntries := make([]object.TreeEntry, 0, len(currentEntries)+1)
	replaced := false
	for _, entry := range currentEntries {
		if entry.Name == targetDir {
			updatedEntries = append(updatedEntries, object.TreeEntry{
				Name: targetDir,
				Mode: filemode.Dir,
				Hash: newSubtreeHash,
			})
			replaced = true
		} else {
			updatedEntries = append(updatedEntries, entry)
		}
	}
	if !found && !replaced {
		updatedEntries = append(updatedEntries, object.TreeEntry{
			Name: targetDir,
			Mode: filemode.Dir,
			Hash: newSubtreeHash,
		})
	}

	sortTreeEntries(updatedEntries)
	return storeTree(repo, updatedEntries)
}

// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
func buildLeafTree(
	repo *git.Repository,
	existingTreeHash plumbing.Hash,
	newEntries []object.TreeEntry,
	opts UpdateSubtreeOptions,
) (plumbing.Hash, error) {
	if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
		sorted := make([]object.TreeEntry, len(newEntries))
		copy(sorted, newEntries)
		sortTreeEntries(sorted)
		return storeTree(repo, sorted)
	}

	// MergeKeepExisting: read existing tree, merge
	existingTree, err := repo.TreeObject(existingTreeHash)
	if err != nil {
		sorted := make([]object.TreeEntry, len(newEntries))
		copy(sorted, newEntries)
		sortTreeEntries(sorted)
		return storeTree(repo, sorted)
	}

	// Build lookup of new entries by name
	newByName := make(map[string]object.TreeEntry, len(newEntries))
	for _, e := range newEntries {
		newByName[e.Name] = e
	}

	// Build delete set
	deleteSet := make(map[string]bool, len(opts.DeleteNames))
	for _, name := range opts.DeleteNames {
		deleteSet[name] = true
	}

	// Merge: keep existing unless overwritten or deleted
	merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
	for _, existing := range existingTree.Entries {
		if deleteSet[existing.Name] {
			continue
		}
		if replacement, ok := newByName[existing.Name]; ok {
			merged = append(merged, replacement)
			delete(newByName, existing.Name)
		} else {
			merged = append(merged, existing)
		}
	}
	// Add remaining new entries (ones that didn't replace an existing entry)
	for _, e := range newEntries {
		if _, stillNew := newByName[e.Name]; stillNew {
			merged = append(merged, e)
		}
	}

	sortTreeEntries(merged)
	return storeTree(repo, merged)
}

// storeTree creates a git tree object from entries and stores it in the repo.
func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
	tree := &object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}
	return hash, nil
}

// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
// Changes are grouped by directory and applied in a single recursive pass.
// Unchanged subdirectories retain their hashes — this is the key optimization
// over FlattenTree + BuildTreeFromEntries for sparse changes.
func ApplyTreeChanges(
	repo *git.Repository,
	rootTreeHash plumbing.Hash,
	changes []TreeChange,
) (plumbing.Hash, error) {
	if len(changes) == 0 {
		return rootTreeHash, nil
	}

	// Read the current root tree
	var currentEntries []object.TreeEntry
	if rootTreeHash != plumbing.ZeroHash {
		tree, err := repo.TreeObject(rootTreeHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", err)
		}
		currentEntries = make([]object.TreeEntry, len(tree.Entries))
		copy(currentEntries, tree.Entries)
	}

	// Group changes by first path segment
	type dirChanges struct {
		subChanges []TreeChange // Changes within this subdirectory
		fileChange *TreeChange  // Direct file change at this level (nil if none)
	}
	grouped := make(map[string]*dirChanges)

	for i := range changes {
		c := changes[i]
		first, rest := splitFirstSegment(c.Path)
		if grouped[first] == nil {
			grouped[first] = &dirChanges{}
		}
		if rest == "" {
			cc := c
			grouped[first].fileChange = &cc
		} else {
			grouped[first].subChanges = append(grouped[first].subChanges, TreeChange{
				Path:  rest,
				Entry: c.Entry,
			})
		}
	}

	// Build entry map for modifications
	entryMap := make(map[string]object.TreeEntry, len(currentEntries))
	for _, e := range currentEntries {
		entryMap[e.Name] = e
	}

	// Process each group
	for name, dc := range grouped {
		if dc.fileChange != nil {
			if dc.fileChange.Entry == nil {
				delete(entryMap, name)
			} else {
				entryMap[name] = object.TreeEntry{
					Name: name,
					Mode: dc.fileChange.Entry.Mode,
					Hash: dc.fileChange.Entry.Hash,
				}
			}
		}
		if len(dc.subChanges) > 0 {
			existingHash := plumbing.ZeroHash
			if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
				existingHash = existing.Hash
			}
			newSubHash, err := ApplyTreeChanges(repo, existingHash, dc.subChanges)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
			}
			entryMap[name] = object.TreeEntry{
				Name: name,
				Mode: filemode.Dir,
				Hash: newSubHash,
			}
		}
	}

	result := make([]object.TreeEntry, 0, len(entryMap))
	for _, e := range entryMap {
		result = append(result, e)
	}
	sortTreeEntries(result)
	return storeTree(repo, result)
}

// WalkCheckpointShards iterates over the two-level shard structure (<id[:2]>/<id[2:]>/)
// in a checkpoint tree, calling fn for each checkpoint found. Skips non-directory entries
// at both levels (e.g., generation.json at the root). The callback receives the parsed
// checkpoint ID and the tree hash of the checkpoint subtree.
func WalkCheckpointShards(repo *git.Repository, tree *object.Tree, fn func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error) error {
	for _, bucketEntry := range tree.Entries {
		if bucketEntry.Mode != filemode.Dir {
			continue
		}
		if len(bucketEntry.Name) != 2 {
			continue
		}

		bucketTree, err := repo.TreeObject(bucketEntry.Hash)
		if err != nil {
			continue
		}

		for _, cpEntry := range bucketTree.Entries {
			if cpEntry.Mode != filemode.Dir {
				continue
			}

			cpID, err := id.NewCheckpointID(bucketEntry.Name + cpEntry.Name)
			if err != nil {
				continue
			}

			if err := fn(cpID, cpEntry.Hash); err != nil {
				return err
			}
		}
	}
	return nil
}

